import subprocess
import sys


def test_condefects_0():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='5 2\n0 0\n1 0\n0 1\n-1 0\n0 -1\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = '6\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


def test_condefects_1():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='1 1\n0 0\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = 'Infinity\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


def test_condefects_2():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='12 2\n-999999999 1000000000\n-999999999 -1000000000\n-1000000000 999999998\n999999999 1000000000\n-1000000000 1000000000\n999999999 -1000000000\n1000000000 1000000000\n1000000000 -999999998\n-1000000000 -1000000000\n-1000000000 -999999998\n1000000000 999999998\n1000000000 -1000000000\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = '46\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


